-- Apply only to an explicitly approved target. No public/business table rewrite.
BEGIN;
CREATE SCHEMA content_studio;
CREATE TABLE content_studio.schema_version(version integer PRIMARY KEY CHECK(version=1));
INSERT INTO content_studio.schema_version VALUES(1);
CREATE TABLE content_studio.projects(id text PRIMARY KEY CHECK(id ~ '^[0-9a-f]{32}$'),title text NOT NULL,revision integer NOT NULL,payload text NOT NULL,updated_at text NOT NULL);
CREATE TABLE content_studio.revisions(project_id text NOT NULL REFERENCES content_studio.projects(id),revision integer NOT NULL,payload text NOT NULL,created_at text NOT NULL,hash text NOT NULL,PRIMARY KEY(project_id,revision));
CREATE TABLE content_studio.media(id text PRIMARY KEY CHECK(id ~ '^[0-9a-f]{32}$'),project_id text NOT NULL REFERENCES content_studio.projects(id),metadata text NOT NULL);
CREATE TABLE content_studio.composition_runs(id text PRIMARY KEY,project_id text NOT NULL REFERENCES content_studio.projects(id),revision integer NOT NULL,payload text NOT NULL,created_at text NOT NULL);
CREATE TABLE content_studio.ai_settings(singleton integer PRIMARY KEY CHECK(singleton=1),payload text NOT NULL);
CREATE TABLE content_studio.ai_gateway(singleton integer PRIMARY KEY CHECK(singleton=1),payload text NOT NULL);
CREATE TABLE content_studio.vk_settings(singleton integer PRIMARY KEY CHECK(singleton=1),payload text NOT NULL);
CREATE TABLE content_studio.vk_intents(id text PRIMARY KEY,project_id text NOT NULL REFERENCES content_studio.projects(id),revision integer NOT NULL,digest text NOT NULL UNIQUE,payload text NOT NULL,state text NOT NULL,expires double precision NOT NULL,result text NOT NULL,created_at text NOT NULL);
CREATE TABLE content_studio.vk_steps(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,intent_id text NOT NULL REFERENCES content_studio.vk_intents(id),stage text NOT NULL,state text NOT NULL,payload text NOT NULL,created_at text NOT NULL);
CREATE UNIQUE INDEX vk_single_dispatch ON content_studio.vk_steps(intent_id) WHERE stage='dispatch_claim';
CREATE INDEX media_project ON content_studio.media(project_id);
CREATE INDEX composition_project ON content_studio.composition_runs(project_id,created_at DESC);
CREATE INDEX intents_project ON content_studio.vk_intents(project_id,created_at DESC);
CREATE TABLE content_studio.project_access(project_id text NOT NULL REFERENCES content_studio.projects(id),user_id bigint NOT NULL REFERENCES public.app_users(id),can_edit boolean NOT NULL DEFAULT false,PRIMARY KEY(project_id,user_id));
CREATE TABLE content_studio.audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id bigint NOT NULL REFERENCES public.app_users(id),action text NOT NULL,object_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE content_studio.migration_receipts(source_sha256 text PRIMARY KEY,manifest text NOT NULL,imported_at timestamptz NOT NULL DEFAULT now());
INSERT INTO content_studio.ai_settings VALUES(1,'{}');
INSERT INTO content_studio.ai_gateway VALUES(1,'{"revision":0,"profiles":{},"tasks":{},"default":"legacy"}');
INSERT INTO content_studio.vk_settings VALUES(1,'{}');
-- Existing least-privilege runtime, no owner role used by web. Only new schema.
-- Granted only where that role exists (the Unified RC deployment); a scratch
-- or CI database without rc_runtime applies the schema and skips the grants.
DO $grants$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'rc_runtime') THEN
        GRANT USAGE ON SCHEMA content_studio TO rc_runtime;
        GRANT SELECT ON content_studio.schema_version TO rc_runtime;
        GRANT SELECT,INSERT,UPDATE ON content_studio.projects,content_studio.revisions,content_studio.media,content_studio.composition_runs,content_studio.ai_settings,content_studio.ai_gateway,content_studio.vk_settings,content_studio.vk_intents,content_studio.vk_steps,content_studio.project_access TO rc_runtime;
        GRANT SELECT,INSERT ON content_studio.audit_events TO rc_runtime;
        GRANT USAGE,SELECT ON SEQUENCE content_studio.vk_steps_id_seq,content_studio.audit_events_id_seq TO rc_runtime;
    END IF;
END
$grants$;
COMMIT;
